  fs=anchor.copy();smooth=u*u*(3-2*u);fs[swing]=liftoff[swing]*(1-smooth)+target[swing]*smooth;fs[swing,2]=cfg['lift']*math.sin(math.pi*u)
  if tm<.5: fs=anchor.copy()
