   q[b+1]=rll;q[b+2]=h+cfg['hipp']*p+cfg['hipd']*o['imu']['gyro'][1];q[b+3]=k;q[b+4]=-h-k+cfg['ankp']*p+cfg['ankd']*o['imu']['gyro'][1]+cfg['ankoff'];q[b]=.1*yaw+.03*o['imu']['gyro'][2]
